<?php
require __DIR__.'/app/bootstrap.php';$user=require_permission('view_all_tickets');$error='';
try{[$where,$params,$filters]=ticket_filter($_GET,$user);}catch(InvalidArgumentException $e){$error=$e->getMessage();[$where,$params,$filters]=ticket_filter([],$user);}
$total=(int)query('SELECT COUNT(*) FROM tickets t'.$where,$params)->fetchColumn();$page=page_number($total);
$rows=query('SELECT t.*,d.name department_name,u.full_name assignee_name FROM tickets t JOIN departments d ON d.id=t.department_id LEFT JOIN users u ON u.id=t.assignee_id'.$where.' ORDER BY t.id DESC LIMIT 25 OFFSET '.(($page-1)*25),$params)->fetchAll();
page_start('Tickets',$user);?><div class="section-head"><div><h2>Keep every request moving</h2><p class="muted">Track ownership, progress and resolutions in one place.</p></div><div class="actions"><?php if(user_can('export_tickets')):?><a class="button button-secondary" href="export.php?<?=e(http_build_query(array_merge($filters,['type'=>'tickets'])))?>">Export CSV</a><?php endif;if(user_can('create_tickets')):?><a class="button" href="create-ticket.php">+ Create ticket</a><?php endif;?></div></div><?php error_notice($error);?><section class="panel"><form method="get" class="filter-grid"><input type="hidden" name="staff_id" value="<?=e($filters['staff_id'])?>"><label>Search<input name="q" placeholder="Ticket, subject or employee" value="<?=e($filters['q'])?>"></label><label>Status<select name="status"><option value="">All statuses</option><?php enum_options(TICKET_STATUSES,$filters['status']);?></select></label><label>Priority<select name="priority"><option value="">All priorities</option><?php enum_options(TICKET_PRIORITIES,$filters['priority']);?></select></label><label>Department<select name="department_id"><option value="">All departments</option><?php options(active_departments(),$filters['department_id']);?></select></label><label>Assigned to<select name="assignee_id"><option value="">Anyone</option><?php options(active_users(),$filters['assignee_id'],'full_name');?></select></label><label>Created from<input type="date" name="from" value="<?=e($filters['from'])?>"></label><label>Created to<input type="date" name="to" value="<?=e($filters['to'])?>"></label><div class="actions"><button class="button">Apply</button><a class="button button-secondary" href="index.php">Reset</a></div></form></section><section class="panel flush"><div class="table-wrap"><table><thead><tr><th>Ticket / subject</th><th>Employee</th><th>Department</th><th>Assigned to</th><th>Priority</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $ticket):?><tr><td><a href="ticket.php?id=<?=$ticket['id']?>"><?=e($ticket['subject'])?></a><span class="cell-secondary"><?=e($ticket['ticket_number'])?></span></td><td><?=e($ticket['employee_name'])?></td><td><?=e($ticket['department_name'])?></td><td><?=e($ticket['assignee_name']??'Unassigned')?></td><td><span class="badge <?=e($ticket['priority'])?>"><?=e(TICKET_PRIORITIES[$ticket['priority']])?></span></td><td><span class="badge <?=e($ticket['status'])?>"><?=e(TICKET_STATUSES[$ticket['status']])?></span></td><td><?=e(substr($ticket['created_at'],0,10))?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty">No tickets match these filters.</td></tr><?php endif;?></tbody></table></div><?php pagination($total,$page);?></section><?php page_end();
